      "action": "Proceed with the calculated result from coder_agent but flag the result as 'Unverified'. Report error: 'Verification step failed, result is unverified.'",
      "reason": "We have a result, but confidence is lower. Better than no result."
    },
    "timeout_handling": {
      "action": "If any phase exceeds its estimated time by 50%, cancel the task and report timeout.",
      "reason": "Total budget is 60s. 30+5+15=50s, leaving 10s buffer. Strict timeouts prevent budget overrun."
    }
  }
